package com.tecsup.pedido.controller; import com.tecsup.pedido.dto.PedidoRequest; import com.tecsup.pedido.model.Pedido; import com.tecsup.pedido.service.PedidoService; import jakarta.validation.Valid; import java.util.List; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/pedidos")public class PedidoController{private final PedidoService s;public PedidoController(PedidoService s){this.s=s;}@GetMapping public List<Pedido> listar(){return s.listar();}@GetMapping("/{id}")public Pedido obtener(@PathVariable Long id){return s.obtener(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED)public Pedido crear(@Valid @RequestBody PedidoRequest d){return s.crear(d);}@PutMapping("/{id}")public Pedido actualizar(@PathVariable Long id,@Valid @RequestBody PedidoRequest d){return s.actualizar(id,d);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void eliminar(@PathVariable Long id){s.eliminar(id);}}
